const raw = $input.first().json;
const list = Array.isArray(raw) ? raw : (raw.data || [raw]);
if (!list || list.length === 0) return [];
return list.filter(item => item && item.id).map(c => ({ json: c }));

const contract = $json;
const renewalDate = contract.renewalDate ? new Date(contract.renewalDate) : null;
if (!renewalDate || isNaN(renewalDate.getTime())) {
  return { ...contract, urgency: 'UNKNOWN', daysRemaining: -1 };
}
const now = new Date();
const diff = renewalDate.getTime() - now.getTime();
const days = Math.ceil(diff / (24 * 60 * 60 * 1000));
let level = 'LOW';
if (days < 0) level = 'EXPIRED';
else if (days <= 7) level = 'CRITICAL';
else if (days <= 30) level = 'HIGH';
else if (days <= 60) level = 'MEDIUM';
return { ...contract, urgency: level, daysRemaining: days };

const contract = $node['Code: Calculate Renewal Urgency'].json;
const rawResponse = $json || {};
const contractId = contract.id;
const customerId = contract.customerId;
const canonicalDate = contract.renewalDate ? String(contract.renewalDate).substring(0, 10) : '';
let parsed = null;
try {
  const candidateText = rawResponse?.candidates?.[0]?.content?.parts?.[0]?.text;
  if (typeof candidateText === 'string' && candidateText.trim()) {
    parsed = JSON.parse(candidateText.trim());
  } else if (typeof rawResponse.recommendation === 'string' || typeof rawResponse.draftContent === 'string') {
    parsed = rawResponse;
  }
} catch {
  parsed = null;
}
const aiRecommendation = parsed && typeof parsed.recommendation === 'string' && parsed.recommendation.trim() ? parsed.recommendation.trim() : '';
const aiDraftContent = parsed && typeof parsed.draftContent === 'string' && parsed.draftContent.trim() ? parsed.draftContent.trim() : '';
const citedContractNumber = parsed && typeof parsed.citedContractNumber === 'string' ? parsed.citedContractNumber.trim() : String(contract.contractNumber || '');
const citedRenewalDate = parsed && typeof parsed.citedRenewalDate === 'string' ? parsed.citedRenewalDate.trim().substring(0, 10) : canonicalDate;
const contractMatches = Boolean(contract.contractNumber && citedContractNumber === contract.contractNumber);
const dateMatches = Boolean(canonicalDate && citedRenewalDate === canonicalDate);
const draftMentionsContract = Boolean(aiDraftContent && contract.contractNumber && aiDraftContent.includes(contract.contractNumber));
const isGrounded = Boolean(contractId && customerId && aiRecommendation && aiDraftContent && contractMatches && dateMatches && draftMentionsContract);
const recommendation = isGrounded ? aiRecommendation : ('Standard renewal terms review for ' + contract.contractNumber);
const draftContent = isGrounded ? aiDraftContent : ('Dear customer, your contract ' + contract.contractNumber + ' is scheduled for renewal on ' + canonicalDate + '. Please review our proposed renewal options.');
return {
  contractId,
  customerId,
  renewalDate: contract.renewalDate,
  urgency: contract.urgency,
  recommendation,
  draftContent,
  aiModel: (typeof $env !== 'undefined' && $env.GEMINI_MODEL) ? $env.GEMINI_MODEL : 'gemini-2.5-flash',
  validationResult: {
    grounded: isGrounded,
    sourceContractId: contractId,
    sourceCustomerId: customerId,
    citedContractNumber,
    citedRenewalDate
  },
  idempotencyKey: 'renewal-draft-' + contractId + '-' + (canonicalDate || 'cycle')
};
